minimal_patch:
在 scripts/lib/daily-task-board.mjs 的 syncFailedSeat 中加入无 artifact 时生成本地 failure evidence 的逻辑，并在 syncDailyBoard 中将 generation_unknown_no_repurchase 纳入 syncFailedSeat 调度列表。具体：
1. 在 syncDailyBoard 的调度判断中，将 ['missing_required_section','generation_failed_no_repurchase','failure_sync_unknown','failed_no_repurchase'] 改为 ['missing_required_section','generation_failed_no_repurchase','generation_unknown_no_repurchase','failure_sync_unknown','failed_no_repurchase']。
2. 在 syncFailedSeat 开头，当 seat.artifact 不存在且 seat.status === 'generation_unknown_no_repurchase' 时，生成本地 failure evidence：
   const evidence = { schema_version: 1, status: 'incomplete_or_failed', date: record.date, task_id: seat.assignment.id, logical_seat: agent, run_key: record.run_key, source_commit: record.source_commit, failure_kind: 'incomplete_or_failed_provider_output', reason: 'generation_unknown_no_repurchase_no_unique_complete_artifact', generated_at: new Date(now).toISOString() };
   const bytes = JSON.stringify(evidence, null, 2) + '\n';
   const hash = digest(bytes);
   const relative = `knowledge/results/daily-board/artifacts/${record.date}-${agent}-${hash}.json`;
   const file = path.join(root, relative);
   fs.mkdirSync(path.dirname(file), { recursive: true });
   fs.writeFileSync(file, bytes, { flag: 'wx' });
   seat.artifact = { path: relative, sha256: hash };
   seat.status = 'failure_sync_unknown';
   saveLedger(root, record);
  然后再执行现有 syncFailedSeat 后续逻辑。
